set query_results_cache_max_age = time(5m);
let now_ = _endTime;
let cur = external_table('SecurityAlert') | where TimeGenerated between (now_ - 7d .. now_) | summarize Current = dcount(SystemAlertId) by AlertName;
let prev = external_table('SecurityAlert') | where TimeGenerated between (now_ - 14d .. now_ - 7d) | summarize Previous = dcount(SystemAlertId) by AlertName;
cur | join kind=fullouter prev on AlertName
| extend AlertName = coalesce(AlertName, AlertName1), Current = coalesce(Current, 0), Previous = coalesce(Previous, 0)
| extend Change = Current - Previous
| extend Status = case(Previous == 0 and Current > 0, "NEW risk", Current == 0, "Resolved", Change > 0, "Increasing", Change < 0, "Decreasing", "Stable")
| project AlertName, Current, Previous, Change, Status
| order by Current desc | take 25

