let t = (s:datetime, e:datetime) { external_table('SecurityAlert') | where TimeGenerated between (s .. e)
  | mv-expand Tactic = split(Tactics, ",") | extend Tactic = trim(" ", tostring(Tactic)) | where isnotempty(Tactic) | summarize Alerts = dcount(SystemAlertId) by Tactic };
t(_endTime - 7d, _endTime) | join kind=fullouter (t(_endTime - 14d, _endTime - 7d) | project-rename Previous = Alerts) on Tactic
| extend Tactic = coalesce(Tactic, Tactic1), Current = coalesce(Alerts, 0), Previous = coalesce(Previous, 0)
| extend ChangePct = iff(Previous == 0, real(null), round(100.0 * (Current - Previous) / Previous, 0))
| project Tactic, Current, Previous, ChangePct | order by Current desc

